'use client'

import { useState, useEffect, useCallback } from 'react'
import Navbar from '@/components/navbar'
import { Sidebar } from '@/components/sidebar'
import { JobCard } from '@/components/job-card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'
import { UnifiedJob } from '@/lib/types/job-types'
import { Search, RefreshCw, AlertCircle, Globe } from 'lucide-react'
import { toast } from 'sonner'

interface JobsResponse {
  success: boolean
  data: UnifiedJob[]
  count: number
  error?: string
  sources: {
    freelancer: boolean
    fiverr: boolean
  }
}

export default function JobsPage() {
  const [jobs, setJobs] = useState<UnifiedJob[]>([])
  const [filteredJobs, setFilteredJobs] = useState<UnifiedJob[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedLevel, setSelectedLevel] = useState<string | null>(null)
  const [selectedSource, setSelectedSource] = useState<string>('all')

  // Fetch jobs from API
  const fetchJobs = useCallback(async (query: string = '', source: string = 'all') => {
    setLoading(true)
    setError(null)
    
    try {
      const params = new URLSearchParams()
      if (query) params.append('q', query)
      if (source !== 'all') params.append('source', source)
      params.append('limit', '50')

      const response = await fetch(`/api/jobs?${params.toString()}`)
      
      if (!response.ok) {
        throw new Error(`Failed to fetch jobs: ${response.status}`)
      }

      const result: JobsResponse = await response.json()
      
      if (!result.success) {
        throw new Error(result.error || 'Failed to fetch jobs')
      }

      setJobs(result.data)
      setFilteredJobs(result.data)
      
      if (result.data.length === 0) {
        toast.info('No jobs found. Try a different search term.')
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to fetch jobs'
      setError(message)
      toast.error(message)
    } finally {
      setLoading(false)
    }
  }, [])

  // Initial load
  useEffect(() => {
    fetchJobs()
  }, [fetchJobs])

  // Apply filters
  useEffect(() => {
    let filtered = [...jobs]

    if (searchTerm.trim()) {
      const lower = searchTerm.toLowerCase()
      filtered = filtered.filter(
        (job) =>
          job.title.toLowerCase().includes(lower) ||
          job.company.toLowerCase().includes(lower) ||
          job.description.toLowerCase().includes(lower) ||
          job.skills.some((s) => s.toLowerCase().includes(lower))
      )
    }

    if (selectedLevel) {
      filtered = filtered.filter((job) => job.level === selectedLevel)
    }

    setFilteredJobs(filtered)
  }, [jobs, searchTerm, selectedLevel])

  const handleSearch = (value: string) => {
    setSearchTerm(value)
    // Debounce API search
    const timeoutId = setTimeout(() => {
      if (value.length >= 3 || value.length === 0) {
        fetchJobs(value, selectedSource)
      }
    }, 500)
    return () => clearTimeout(timeoutId)
  }

  const handleLevelChange = (level: string) => {
    setSelectedLevel(selectedLevel === level ? null : level)
  }

  const handleSourceChange = (source: string) => {
    setSelectedSource(source)
    fetchJobs(searchTerm, source)
  }

  const handleRefresh = () => {
    fetchJobs(searchTerm, selectedSource)
    toast.success('Jobs refreshed!')
  }

  const handleReset = () => {
    setSearchTerm('')
    setSelectedLevel(null)
    setSelectedSource('all')
    fetchJobs('', 'all')
  }

  // Loading skeleton
  const JobSkeleton = () => (
    <Card className="p-6 border border-border">
      <div className="space-y-4">
        <div className="flex items-start justify-between">
          <div className="space-y-2 flex-1">
            <Skeleton className="h-6 w-3/4" />
            <Skeleton className="h-4 w-1/2" />
          </div>
          <Skeleton className="h-9 w-20" />
        </div>
        <div className="flex gap-2">
          <Skeleton className="h-4 w-24" />
          <Skeleton className="h-4 w-24" />
        </div>
        <Skeleton className="h-16 w-full" />
        <div className="flex gap-2 pt-2">
          <Skeleton className="h-6 w-16" />
          <Skeleton className="h-6 w-16" />
          <Skeleton className="h-6 w-16" />
        </div>
      </div>
    </Card>
  )

  return (
    <main className="min-h-screen bg-background w-full">
      <Navbar />

      <div className="flex gap-8">
        <Sidebar />
        <div className="flex-1 w-full px-6 py-8">
          {/* Header */}
          <div className="mb-8 flex items-start justify-between">
            <div>
              <h1 className="text-4xl font-bold mb-2">Browse Jobs</h1>
              <p className="text-muted-foreground">
                Find your next opportunity from Freelancer.com and Fiverr
              </p>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleRefresh}
              disabled={loading}
              className="flex items-center gap-2"
            >
              <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
              Refresh
            </Button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
            {/* Sidebar - Filters */}
            <div className="lg:col-span-1">
              <Card className="p-6 border border-border sticky top-20">
                <h3 className="font-semibold text-lg mb-4 text-foreground">Filters</h3>

                {/* Search in filters */}
                <div className="mb-6">
                  <label className="text-sm font-medium text-foreground mb-2 block">
                    Search
                  </label>
                  <div className="relative">
                    <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <Input
                      placeholder="Title, skill, company..."
                      value={searchTerm}
                      onChange={(e) => handleSearch(e.target.value)}
                      className="pl-8"
                    />
                  </div>
                </div>

                {/* Source Filter */}
                <div className="mb-6">
                  <label className="text-sm font-medium text-foreground mb-2 block">
                    Source
                  </label>
                  <div className="space-y-2">
                    {[
                      { value: 'all', label: 'All Sources' },
                      { value: 'freelancer', label: 'Freelancer.com' },
                      { value: 'fiverr', label: 'Fiverr' }
                    ].map((source) => (
                      <button
                        key={source.value}
                        onClick={() => handleSourceChange(source.value)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm transition-all ${
                          selectedSource === source.value
                            ? 'bg-primary text-white'
                            : 'bg-muted hover:bg-accent/20 text-foreground'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <Globe className="w-4 h-4" />
                          {source.label}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>

                {/* Level Filter */}
                <div className="mb-6">
                  <label className="text-sm font-medium text-foreground mb-2 block">
                    Experience Level
                  </label>
                  <div className="space-y-2">
                    {['Entry', 'Mid', 'Senior'].map((level) => (
                      <button
                        key={level}
                        onClick={() => handleLevelChange(level)}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm transition-all ${
                          selectedLevel === level
                            ? 'bg-primary text-white'
                            : 'bg-muted hover:bg-accent/20 text-foreground'
                        }`}
                      >
                        {level}
                      </button>
                    ))}
                  </div>
                </div>

                <Button
                  variant="outline"
                  className="w-full mt-4"
                  onClick={handleReset}
                >
                  Reset Filters
                </Button>
              </Card>
            </div>

            {/* Main Content - Job List */}
            <div className="lg:col-span-3">
              {/* Results count */}
              <div className="mb-4 flex items-center justify-between">
                <p className="text-sm text-muted-foreground">
                  {loading ? (
                    'Loading jobs...'
                  ) : (
                    <>Showing <span className="font-medium text-foreground">{filteredJobs.length}</span> jobs</>
                  )}
                </p>
                <div className="flex gap-2">
                  <Badge variant="secondary" className="text-xs">
                    Live Data
                  </Badge>
                </div>
              </div>

              <div className="grid grid-cols-1 gap-4">
                {loading ? (
                  // Loading skeletons
                  <>
                    <JobSkeleton />
                    <JobSkeleton />
                    <JobSkeleton />
                    <JobSkeleton />
                  </>
                ) : error ? (
                  <Card className="p-12 text-center">
                    <AlertCircle className="w-12 h-12 text-destructive mx-auto mb-4" />
                    <p className="text-muted-foreground mb-4">{error}</p>
                    <Button onClick={handleRefresh}>Try Again</Button>
                  </Card>
                ) : filteredJobs.length > 0 ? (
                  filteredJobs.map((job) => (
                    <JobCard key={job.id} job={job} />
                  ))
                ) : (
                  <Card className="p-12 text-center">
                    <p className="text-muted-foreground">No jobs found matching your criteria.</p>
                    <Button
                      variant="link"
                      onClick={handleReset}
                      className="mt-2"
                    >
                      Clear all filters
                    </Button>
                  </Card>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </main>
  )
}
